R=[{"h": "Indicativo o subjuntivo", "p": ["Indicativo: lo que se afirma como real. Subjuntivo: lo deseado, dudado, sentido, posible o todavía no ocurrido.", "La pregunta útil: ¿la oración principal afirma un hecho, o reacciona ante algo que no se afirma?"]}, {"h": "Voluntad e influencia: querer que, pedir que", "p": ["Si el sujeto cambia, el verbo que sigue va en subjuntivo."], "ex": [["Quiero que me dejes ir.", "tatoeba", "dejes", "I want you to let me go."], ["Ojalá que él me espere.", "tatoeba", "espere", "I hope he'll wait for me."], ["—No, no —replicó la duquesa—, buena está ésta, y quiero que el duque la vea.", "quijote", "vea", null], ["Negósela Sancho, y mandó que se levantase y dijese lo que quisiese.", "quijote", "levantase", null]]}, {"h": "Emoción y valoración", "ex": [["Me alegra que Tom esté bien.", "tatoeba", "esté", "I'm glad Tom's OK."], ["Me alegra que te guste.", "tatoeba", "guste", "Glad you like it."]]}, {"h": "Duda y negación: creo que / no creo que", "p": ["creer, pensar, parecer afirmativos llevan indicativo; negados, subjuntivo."], "ex": [["Creo que es un mito.", "tatoeba", "es", "I think it's a myth."], ["No creo que sea hora.", "tatoeba", "sea", "I don't think it's time."]]}, {"h": "Cuando, hasta que, en cuanto", "p": ["Con algo que todavía no ha pasado: subjuntivo. Con costumbres o el pasado: indicativo."], "ex": [["Cuando tenga vacaciones iré al mar Mediterráneo.", "tatoeba", "tenga", "When I have a vacation I'll go to the Mediterranean Sea."], ["Esperaré aquí hasta que vuelva.", "tatoeba", "vuelva", "I will wait here until he comes back."], ["Cuando llueve los autobuses suelen retrasarse.", "tatoeba", "llueve", "When it rains, the buses tend to run late."], ["Cuando era niño no podía comer pescado.", "tatoeba", "era", "I couldn't eat fish when I was a child."], ["Ni tengo para qué enturbiar el agua clara destos arroyos, los cuales me han de dar de beber cuando tenga gana.", "quijote", "tenga", null]]}, {"h": "Aunque: hecho o posibilidad", "p": ["aunque + indicativo: «although» (es un hecho). aunque + subjuntivo: «even if» (no importa si es así)."], "ex": [["Aunque es pobre, ella es feliz.", "tatoeba", "es", "Though she is poor, she is happy."], ["Aunque sea duro, debo hacerlo.", "tatoeba", "sea", "Whether it may be hard or not, I must do it."], ["—Ya sabe el buen Sancho que lo que una vez promete un caballero procura cumplirlo, aunque le cueste la vida.", "quijote", "cueste", null], ["—No sacaremos nada aunque vengan veinte si no los visitas.", "orgullo", "vengan", null]]}, {"h": "Para que, sin que, antes de que: siempre subjuntivo", "ex": [["Se apartó para que pasara ella.", "tatoeba", "pasara", "He stepped aside for her to pass."], ["Lo hizo sin que yo lo supiera.", "tatoeba", "supiera", "He did it unbeknownst to me."], ["Vete antes de que te vean.", "tatoeba", "vean", "Go away before they see you here."]]}, {"h": "Algo que no se sabe si existe", "ex": [["Necesito un abogado que hable francés.", "tatoeba", "hable", "I need a lawyer who can speak French."]]}, {"h": "Si: real, hipotético, imposible", "p": ["si + presente → presente o futuro (posible).", "si + imperfecto de subjuntivo → condicional (hipotético).", "si + pluscuamperfecto de subjuntivo → condicional compuesto (ya imposible).", "Nunca: «si + presente de subjuntivo»."], "ex": [["Si llueve mañana, no voy.", "tatoeba", "llueve", "If it rains tomorrow, I'm not going."], ["Si fuera tú, lo ignoraría.", "tatoeba", "fuera", "Were I you, I would ignore it."], ["Si hubiera sido rico, te habría dado dinero.", "tatoeba", "hubiera", "If I had been rich, I would have given you some money."], ["—Si yo fuera tan rico como el señor Darcy —exclamó uno de los Lucas, que había venido con sus hermanas— no me cuidaría de si era o no orgulloso.", "orgullo", "fuera", null], ["—Si yo tuviera dineros —dijo el paje—, preguntara al señor mono qué me ha de suceder en la peregrinación que llevo.", "quijote", "preguntara", null]]}, {"h": "Como si: siempre imperfecto (o pluscuamperfecto) de subjuntivo", "ex": [["Habla como si supiera de todo.", "tatoeba", "supiera", "He talks as if he knew everything."], ["Siento como si nunca te hubiera hecho justicia ni amado como te mereces.", "orgullo", "hubiera", null], ["—Así sería —dijo Sancho—; porque a buena fe que andaba Rocinante como si fuera asno de gitano con azogue en los oídos.", "quijote", "fuera", null]]}, {"h": "Concordancia de tiempos", "p": ["Verbo principal en presente → presente de subjuntivo. En pasado → imperfecto de subjuntivo."], "ex": [["Quiero que sigas a Tom.", "tatoeba", "sigas", "I want you to follow Tom."], ["No temía que el hecho se propagase por conducto de él.", "orgullo", "propagase", null], ["Dorotea la tomó por la mano y la llevó a sentar junto a sí, y le rogó que se quitase el embozo.", "quijote", "quitase", null]]}, {"h": "Quisiera, pudiera: -ra o -se", "p": ["Las dos formas del imperfecto de subjuntivo valen lo mismo: tuviera = tuviese. La app acepta las dos.", "En los clásicos, la forma en -ra a veces ocupa el lugar del condicional: «preguntara» = preguntaría. Hoy se conserva en quisiera, pudiera, debiera."], "ex": [["Unas bellotas envié a mi señora la duquesa; yo quisiera que fueran de oro.", "quijote", "quisiera", null], ["¿Qué dijera el señor Amadís si lo tal oyera?", "quijote", "dijera", null]]}, {"h": "Futuro de probabilidad", "p": ["El futuro también expresa suposición sobre el presente: «¿quién será?» = who could it be?"], "ex": [["¿Quién será a estas horas de la mañana?", "tatoeba", "será", "Who could it be at this time of day?"]]}, {"h": "Pretérito o imperfecto: el relato", "p": ["El imperfecto pinta el escenario; el pretérito hace avanzar la historia. Con el mismo verbo, cambia lo que se cuenta."], "ex": [["Murió cuando tenía 54 años.", "tatoeba", "tenía", "She died when she was 54 years old."], ["Todo estaba arreglado cuando yo llegué; así que mi curiosidad no se vió tan horriblemente atormentada como la tuya parece estarlo.", "orgullo", "llegué", null], ["El señor Hurst y Bingley jugaban al piquet, y la esposa del primero contemplaba la partida.", "orgullo", "jugaban", null], ["En esto, descubrieron treinta o cuarenta molinos de viento que hay en aquel campo", "quijote", "descubrieron", null]]}, {"h": "Verbos que cambian de sentido en pretérito", "p": ["conocía = I knew · conocí = I met", "sabía = I knew · supe = I found out", "no quería = I didn’t want · no quise = I refused", "podía = I was able · pude = I managed"], "ex": [["Ayer conocí a tu padre.", "tatoeba", "conocí", "I met your dad yesterday."], ["No quise herir a nadie.", "tatoeba", "quise", "I meant no harm."], ["No pude parar de reír.", "tatoeba", "pude", "I couldn't stop laughing."], ["El ventero, que no conocía a don Quijote, tan admirado le tenían sus locuras como su liberalidad.", "quijote", "conocía", null]]}, {"h": "En el Perú: ustedes, y el «le» de los libros", "p": ["En el Perú se usa ustedes para cualquier grupo; el vosotros de los libros es de España. La app deja el vosotros para el final.", "En los dos libros, escritos en España, aparece «le» como complemento directo para un hombre (le vi = lo vi). En el Perú se dice lo."], "ex": [["Ha de saber usted que la primera vez que le vi en Hertford fué en un baile, y en ese baile ¿qué cree usted que hizo?", "orgullo", "le vi", null], ["Pues sepa que le conozco, por más que se encubra el rostro, y sepa que le entiendo, por más que disimule sus embustes.", "quijote", "le conozco", null]]}, {"h": "Leer Orgullo y prejuicio (1924)", "p": ["Traducción de José Jordán de Urríes y Azara, 1924, con la ortografía de entonces: fué, vió, dió (hoy fue, vio, dio). Isabel es Elizabeth; Juana, Jane; Catalina, Kitty. El pronombre a veces va detrás del verbo: vedóle = le vedó."], "ex": [["El delicado sentido del honor que poseía Juana vedóle hablar en particular a Isabel de lo que Lydia dejara escapar.", "orgullo", "vedóle", null]]}, {"h": "Leer el Quijote", "p": ["Formas de 1605: deste = de este, della = de ella, dél = de él, mesmo = mismo, agora = ahora, vuestra merced = usted. El futuro de subjuntivo (hubiere, fuere) hoy solo vive en textos legales."], "ex": [["¿Qué padre o qué madre se dolerá della?", "quijote", "della", null], ["—El enemigo que yo hubiere vencido quiero que me le claven en la frente.", "quijote", "hubiere", null], ["Díjole Sancho que mirase que era hora de comer.", "quijote", "Díjole", null]]}],
FIRST=[["En un lugar de la Mancha, de cuyo nombre no quiero acordarme, no ha mucho tiempo que vivía un hidalgo de los de lanza en astillero, adarga antigua, rocín flaco y galgo corredor.", "quijote", "vivía", null], ["Es verdad universalmente admitida que un soltero poseedor de buena fortuna tiene que necesitar una mujer.", "orgullo", "Es", null]];
